<?php

namespace App\Models\Concerns;

use Illuminate\Support\Facades\Storage;

/**
 * Depth effect (like the iPhone lock screen): a transparent cutout of the cover photo's
 * subject, drawn in front of the title. Generated by `php artisan anubhootee:depth`.
 */
trait HasDepthCutout
{
    /** Subjects smaller than this, or bigger than this share of the photo, don't get the effect. */
    public const DEPTH_MIN = 0.01;

    public const DEPTH_MAX = 0.6;

    protected static function bootHasDepthCutout(): void
    {
        // A new cover photo makes the old cutout wrong: drop it so it gets regenerated.
        static::saving(function ($model) {
            if ($model->isDirty('cover') && ! $model->isDirty('cover_fg') && $model->cover_fg) {
                Storage::disk('public')->delete($model->cover_fg);
                $model->cover_fg = null;
                $model->cover_fg_coverage = null;
            }
            // A cutout uploaded by hand: trust it (no coverage limits).
            if ($model->isDirty('cover_fg') && ! $model->isDirty('cover_fg_coverage')) {
                $model->cover_fg_coverage = null;
            }
        });
    }

    /** URL of the subject cutout, or null when this photo shouldn't use the depth effect. */
    public function depthUrl(): ?string
    {
        if (! $this->cover || ! $this->cover_fg) {
            return null;
        }
        $c = $this->cover_fg_coverage;
        if ($c !== null && ($c < self::DEPTH_MIN || $c > self::DEPTH_MAX)) {
            return null;
        }

        return Storage::disk('public')->url($this->cover_fg);
    }
}
